data = sys.stdin.read().split()
n, target = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
pairs = set()
for i in range(n):
    for j in range(i + 1, n):
        if a[i] + a[j] == target:
            pairs.add((min(a[i], a[j]), max(a[i], a[j])))
print(len(pairs))

